window.__votdWeek && window.__votdWeek({"week":"2029-10-01","reading":"Doctrine and Covenants 109–110","days":[{"d":"2029-10-01","ref":"D&C 109:30","b":"D&C","c":109,"v":30,"he":"וַאֲשֶׁר כׇּל מַעֲשֵׂיהֶם יוּבְאוּ לְאַיִן וְיִסָּחֲפוּ בַּבָּרָד וּבַמִּשְׁפָּטִים אֲשֶׁר תִּשְׁלַח עֲלֵיהֶם בְּאַפֶּךָ לְמַעַן יִהְיֶה קֵץ לַכְּזָבִים וְלַדִּבּוֹת עַל עַמֶּךָ׃","en":"And that all their works may be brought to naught, and be swept away by the hail, and by the judgments which thou wilt send upon them in thine anger, that there may be an end to lyings and slanders against thy people."},{"d":"2029-10-02","ref":"D&C 109:64","b":"D&C","c":109,"v":64,"he":"וּבְנֵי יְהוּדָה יָחֵלּוּ לָשׁוּב אֶל הָאֲרָצוֹת אֲשֶׁר נָתַתָּ לְאַבְרָהָם אֲבִיהֶם׃","en":"And the children of Judah may begin to return to the lands which thou didst give to Abraham, their father."},{"d":"2029-10-03","ref":"D&C 109:65","b":"D&C","c":109,"v":65,"he":"וַעֲשֵׂה אֲשֶׁר שְׁאֵרִית יַעֲקֹב אֲשֶׁר קֻלְלוּ וְהֻכּוּ בִּגְלַל פִּשְׁעָם יָשׁוּבוּ מִדַּרְכָּם הַפֶּרֶא וְהַפָּרוּעַ אֶל מְלוֹא בְּשׂוֹרַת עוֹלָם׃","en":"And cause that the remnants of Jacob, who have been cursed and smitten because of their transgression, be converted from their wild and savage condition to the fulness of the everlasting gospel;"},{"d":"2029-10-04","ref":"D&C 109:74","b":"D&C","c":109,"v":74,"he":"וְתִתְעַדֶּה כַּכַּלָּה לַיּוֹם אֲשֶׁר תִּגְלֶה אֶת־הַשָּׁמַיִם וְתָמֵס הֶהָרִים מִלְּפָנֶיךָ וְהָעֲמָקִים יִנָּשְׂאוּ וְהַמְּקוֹמוֹת הָעֲקֻבִּים יְיֻשָּׁרוּ לְמַעַן יִמָּלֵא כְבוֹדְךָ אֶת־הָאָרֶץ׃","en":"And be adorned as a bride for that day when thou shalt unveil the heavens, and cause the mountains to flow down at thy presence, and the valleys to be exalted, the rough places made smooth; that thy glory may fill the earth;"},{"d":"2029-10-05","ref":"D&C 110:2","b":"D&C","c":110,"v":2,"he":"רָאִינוּ אֶת־יְהוָה עֹמֵד עַל מַעֲקֵה הַמִּגְדָּל לְפָנֵינוּ וְתַחַת רַגְלָיו מַעֲשֵׂה לִבְנַת זָהָב טָהוֹר בְּמַרְאֶה כְּעֵין הַחַשְׁמַל׃","en":"We saw the Lord standing upon the breastwork of the pulpit, before us; and under his feet was a paved work of pure gold, in color like amber."},{"d":"2029-10-06","ref":"D&C 110:3","b":"D&C","c":110,"v":3,"he":"עֵינָיו כְּלַבַּת אֵשׁ וּשְׂעַר רֹאשׁוֹ לָבָן כַּשֶּׁלֶג הַטָּהוֹר וּפָנָיו הִזְהִירוּ מִזֹּהַר הַשֶּׁמֶשׁ וְקוֹלוֹ כְּקוֹל שְׁאוֹן מַיִם רַבִּים גַּם קוֹל יְהוָה לֵאמֹר׃","en":"His eyes were as a flame of fire; the hair of his head was white like the pure snow; his countenance shone above the brightness of the sun; and his voice was as the sound of the rushing of great waters, even the voice of Jehovah, saying:"},{"d":"2029-10-07","ref":"D&C 110:13","b":"D&C","c":110,"v":13,"he":"אַחֲרֵי כְלוֹת הַמַּרְאֶה הַזֶּה פָּרַץ עָלֵינוּ מַרְאֶה אַחֵר גָּדוֹל וְנִכְבָּד כִּי אֵלִיָּהוּ הַנָּבִיא אֲשֶׁר נִלְקַח הַשָּׁמַיְמָה מִבְּלִי טְעֹם מָוֶת עָמַד לְפָנֵינוּ וַיֹּאמֶר׃","en":"After this vision had closed, another great and glorious vision burst upon us; for Elijah the prophet, who was taken to heaven without tasting death, stood before us, and said:"}]});
